import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第四十六卦 升 地風升 坤上巽下","description":"周易 - 第四十六卦 升 地風升 坤上巽下","frontmatter":{"title":"第四十六卦 升 地風升 坤上巽下","description":"周易 - 第四十六卦 升 地風升 坤上巽下"},"headers":[],"relativePath":"classics/zhouyi/047.md","filePath":"classics/zhouyi/047.md"}'),l={name:"classics/zhouyi/047.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="升" tabindex="-1">升 <a class="header-anchor" href="#升" aria-label="Permalink to “升”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>元亨，用見大人，勿恤，南征吉。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>柔以時升，巽而順，剛中而應，是以大亨。用見大人，勿恤；有慶也。南征吉，志行也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>地中生木，升；君子以順德，積小以高大。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>允升，大吉。象曰：允升大 吉，上合志也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>孚乃利用禴，無咎。象曰：九二之孚，有喜也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>升虛邑。象曰：升虛邑，無所疑也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>王用亨於岐山，吉無咎。象曰：王用亨於岐山，順事也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>貞吉，升階。象曰：貞吉升階，大得志也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>冥升，利於不息之貞。象曰：冥升在上，消不富也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
